// Synthetic marine radar. Returns are ray-cast from this prototype's chart geometry.
// No antenna, real vessel traffic or external data is connected.
const radarModel={gain:68,sea:28,rain:15,opacity:75,rotation:0,freeze:false,guard:false,frame:0,last:0,samples:null};
let radarRequest=0;
const radarRandom=n=>{const x=Math.sin(n*12.9898+78.233)*43758.5453;return x-Math.floor(x);};
function generateRadarSamples(){
 const mask=document.createElement('canvas');mask.width=1000;mask.height=630;const ctx=mask.getContext('2d',{willReadFrequently:true});ctx.fillStyle='#fff';$$('.chart-land').forEach(p=>ctx.fill(new Path2D(p.getAttribute('d'))));const pixels=ctx.getImageData(0,0,1000,630).data;const samples=[];
 for(let spoke=0;spoke<900;spoke++){const a=spoke/900*Math.PI*2,dx=Math.sin(a),dy=-Math.cos(a);for(let r=22;r<620;r+=2){const x=Math.round(500+dx*r),y=Math.round(420+dy*r);if(x<0||x>=1000||y<0||y>=630)break;if(pixels[(y*1000+x)*4+3]>0){const strength=.55+radarRandom(spoke+31)*.4;for(let j=0;j<7;j++){const rr=r+j*1.65+radarRandom(spoke*13+j)*4;samples.push({x:500+dx*rr,y:420+dy*rr,r:rr,a,amp:strength*(1-j/9),kind:'coast',size:1.2+radarRandom(j+spoke)*1.7});}break;}}}
 [[690,307],[430,366],[718,454],[784,77],[545,270],[605,445]].forEach(([x,y],i)=>{for(let j=0;j<30;j++){const xx=x+(radarRandom(i*70+j)-.5)*10,yy=y+(radarRandom(i*19+j+4)-.5)*5,dx=xx-500,dy=yy-420;samples.push({x:xx,y:yy,r:Math.hypot(dx,dy),a:(Math.atan2(dx,-dy)+Math.PI*2)%(Math.PI*2),amp:.8+radarRandom(j)*.2,kind:'target',size:1.2});}});
 for(let i=0;i<900;i++){const a=radarRandom(i+900)*Math.PI*2,r=Math.sqrt(radarRandom(i+2400))*95;samples.push({x:500+Math.sin(a)*r,y:420-Math.cos(a)*r,r,a,amp:radarRandom(i+3200)*.5,kind:'sea',size:1});}
 for(let i=0;i<400;i++){const x=650+(radarRandom(i+8000)-.5)*105,y=350+(radarRandom(i+9300)-.5)*90,dx=x-500,dy=y-420;samples.push({x,y,r:Math.hypot(dx,dy),a:(Math.atan2(dx,-dy)+Math.PI*2)%(Math.PI*2),amp:radarRandom(i+6000)*.3,kind:'rain',size:1.4});}
 return samples;
}
function radarControls(){return `<div class="radar-mode-label">${tag('SIMULATED ECHO','warning')}${tag(state.radar?'SWEEP ACTIVE':'STANDBY','neutral')}</div>${toggle('Radar active','radarPower',state.radar)}<label class="field">Range<select id="radarRange" aria-label="Radar range">${['0.5','1.5','3','6'].map(n=>`<option value="${n}" ${n===state.radarRange?'selected':''}>${n} nm</option>`).join('')}</select></label>${[['Gain','gain'],['Sea clutter','sea'],['Rain suppression','rain'],['Overlay opacity','opacity']].map(([label,key])=>`<label class="range-field"><span>${label}<output id="radar-${key}">${radarModel[key]}%</output></span><input type="range" min="0" max="100" value="${radarModel[key]}" aria-label="${label}" data-radar-model="${key}"></label>`).join('')}${toggle('Guard zone','radarGuard',radarModel.guard,'Ahead of the bow · 0.25–0.5 nm')}${toggle('Pause sweep','radarPause',radarModel.freeze)}${note('Coastline returns, vessel echoes and clutter are generated from the demo scene. Gain, clutter suppression and range change the visible returns.')}`;}
function radarView(){return `<div class="view-header"><div><span class="eyebrow">RADAR / SITUATIONAL AWARENESS</span><h1>Read beyond the chart.</h1><p>Sweeping returns, a clear horizon.</p></div><button class="view-back" data-action="back" data-context-return></button></div><div class="radar-layout"><div class="radar-display"><div class="radar-scope"><canvas id="radarFocusCanvas" aria-label="Simulated radar echo display"></canvas><div class="radar-crosshair"></div><span class="radar-north">N</span><div class="radar-scope-caption"><b>${state.radar?state.radarRange+' NM':'STANDBY'}</b><span>HEAD ${String(state.heading).padStart(3,'0')}° · NORTH UP</span></div></div><div class="radar-legend"><span><i class="echo-dot"></i> Coastline & vessel returns</span><span>24 rpm · simulated</span></div></div><div class="radar-control-panel">${radarControls()}</div></div>`;}
function syncRadar(){const obsolete=$('#radarMapLayer');if(obsolete)obsolete.style.display='none';let canvas=$('#radarEchoCanvas');if(!canvas){canvas=document.createElement('canvas');canvas.id='radarEchoCanvas';canvas.setAttribute('aria-label','Demo radar echo overlay');$('#chartCanvas').append(canvas);}canvas.hidden=!state.radar;let badge=$('#radarOverlayBadge');if(!badge){badge=document.createElement('button');badge.id='radarOverlayBadge';badge.className='radar-overlay-badge';badge.dataset.panel='radarControl';$('#chartView').append(badge);}badge.hidden=!state.radar;badge.innerHTML='<i class="echo-dot"></i> RADAR ECHO <span>SIMULATED · '+state.radarRange+' NM</span>'+icon('sliders');if(state.radar&&!radarModel.samples)radarModel.samples=generateRadarSamples();if(state.radar&&!radarRequest)radarRequest=requestAnimationFrame(radarFrame);if(!state.radar){cancelAnimationFrame(radarRequest);radarRequest=0;drawRadarCanvas($('#radarFocusCanvas'),true,performance.now());}}
function drawRadarCanvas(canvas,focus,time){if(!canvas)return;const rect=canvas.getBoundingClientRect();if(rect.width<1)return;const dpr=Math.min(devicePixelRatio,2),w=Math.round(rect.width*dpr),h=Math.round(rect.height*dpr);if(canvas.width!==w||canvas.height!==h){canvas.width=w;canvas.height=h;}const ctx=canvas.getContext('2d');ctx.setTransform(1,0,0,1,0,0);ctx.clearRect(0,0,w,h);const range=Number(state.radarRange)*165;let unit;
 if(focus){unit=Math.min(w,h)/(range*2.12);ctx.setTransform(unit,0,0,unit,w/2-500*unit,h/2-420*unit);}else{const m=$('#mapTransform').getScreenCTM();unit=Math.hypot(m.a,m.b)*dpr;ctx.setTransform(m.a*dpr,m.b*dpr,m.c*dpr,m.d*dpr,(m.e-rect.x)*dpr,(m.f-rect.y)*dpr);}
 ctx.save();ctx.beginPath();ctx.arc(500,420,range,0,Math.PI*2);ctx.clip();
 const alpha=focus?1:radarModel.opacity/100;
 ctx.strokeStyle=focus?'rgba(144,210,181,.17)':'rgba(29,107,77,.22)';ctx.lineWidth=.7/unit;for(let ring=1;ring<=3;ring++){ctx.beginPath();ctx.arc(500,420,range*ring/3,0,Math.PI*2);ctx.stroke();}
 if(state.radar){const sweep=radarModel.rotation;const night=state.theme==='night';const gain=.35+radarModel.gain/85;for(const p of radarModel.samples||[]){if(p.r>range)continue;const age=(sweep-p.a+Math.PI*2)%(Math.PI*2);let amp=p.amp*gain*(.3+.7*Math.exp(-age*1.2))*alpha;if(p.kind==='sea')amp*=Math.pow(1-radarModel.sea/100,2);if(p.kind==='rain')amp*=Math.pow(1-radarModel.rain/100,2);if(amp<.07)continue;ctx.fillStyle=(focus||state.theme!=='day')?`rgba(115,${night?176:239},151,${Math.min(.95,amp)})`:`rgba(12,137,63,${Math.min(.93,amp)})`;ctx.fillRect(p.x,p.y,p.size,p.size);}
  for(let i=0;i<28;i++){const a=sweep-i*.008;ctx.beginPath();ctx.moveTo(500,420);ctx.lineTo(500+Math.sin(a)*range,420-Math.cos(a)*range);ctx.strokeStyle=`rgba(115,225,157,${(.21-i*.007)*alpha})`;ctx.lineWidth=range*.009;ctx.stroke();}
  if(radarModel.guard){
   // The sector follows the bow in chart coordinates. The canvas transform
   // already applies the selected chart orientation, so do not rotate it twice.
   const centre=(state.heading-90)*Math.PI/180,halfWidth=Math.PI*.35;
   ctx.beginPath();ctx.arc(500,420,.5*165,centre-halfWidth,centre+halfWidth);ctx.arc(500,420,.25*165,centre+halfWidth,centre-halfWidth,true);ctx.closePath();ctx.fillStyle='rgba(225,184,106,.08)';ctx.fill();ctx.strokeStyle='rgba(225,184,106,.7)';ctx.lineWidth=1/unit;ctx.setLineDash([4/unit,5/unit]);ctx.stroke();ctx.setLineDash([]);
  }
 }
 ctx.restore();if(focus){ctx.save();ctx.translate(500,420);ctx.rotate(state.heading*Math.PI/180);ctx.fillStyle='#bee7cf';ctx.beginPath();ctx.moveTo(0,-10);ctx.lineTo(5,7);ctx.lineTo(0,3);ctx.lineTo(-5,7);ctx.closePath();ctx.fill();ctx.restore();}
}
function radarFrame(time){radarRequest=0;if(!state.radar)return;if(time-radarModel.last>65){if(!radarModel.freeze&&!matchMedia('(prefers-reduced-motion: reduce)').matches)radarModel.rotation=(time/2500*Math.PI*2)%(Math.PI*2);else if(!radarModel.rotation)radarModel.rotation=Math.PI/3;drawRadarCanvas($('#radarEchoCanvas'),false,time);if(state.view==='radar')drawRadarCanvas($('#radarFocusCanvas'),true,time);radarModel.last=time;radarModel.frame++;}radarRequest=requestAnimationFrame(radarFrame);}
actions.radarPower=()=>{state.radar=!state.radar;syncRadar();if(state.panel==='radarControl')renderPanel();else if(state.view==='radar'){renderView();updateNavigation();}else if(state.panel)renderPanel();};
actions.toggleRadar=()=>{state.radar=!state.radar;syncRadar();if(state.panel)renderPanel();};
actions.radarOverlay=()=>{state.radar=true;chartContext();syncChart();syncRadar();};
actions.radarPause=()=>{radarModel.freeze=!radarModel.freeze;if(state.panel)renderPanel();else renderView();};
actions.radarGuard=()=>{radarModel.guard=!radarModel.guard;if(state.panel)renderPanel();else renderView();};
document.addEventListener('input',e=>{if(e.target.dataset.radarModel){radarModel[e.target.dataset.radarModel]=+e.target.value;$('#radar-'+e.target.dataset.radarModel).textContent=e.target.value+'%';}});
